def transform(grid):
    if not grid:
        return grid

    # Count to find background color
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1

    background = max(counts, key=counts.get)
    rows = len(grid)
    cols = len(grid[0])

    # Create output grid
    output = [[grid[i][j] for j in range(cols)] for i in range(rows)]

    # For each 8 that is between two non-background cells, change to 2
    for i in range(rows):
        for j in range(1, cols - 1):
            if output[i][j] == background:
                if output[i][j-1] != background and output[i][j+1] != background:
                    output[i][j] = 2

    return output
